mapper.select:
/* selectReqList - Lee MS */ B.INCDNT_TTL_NM AS INCDNT_TTL_NM, /* 사건제목명 */ B.INCDNT_OCRN_YMD AS INCDNT_OCRN_YMD, /* 사건발생일자 */ A.ACTN_TTL_NM AS ACTN_TTL_NM, /* 조치제목명 */ A.ACTN_RPT_YMD AS ACTN_RPT_YMD, /* 조치보고일자 */ C##RG.DEC_B64(D.FLNM_ENCPT) AS PIC_NM, /* 담당자명 */ C.INST_NM AS INST_NM, /* 기관명 */ A.EMRG_CNTRMS_INCDNT_NO AS EMRG_CNTRMS_INCDNT_NO, /*긴급대응사건번호 */ A.INCDNT_NO_SN AS INCDNT_NO_SN /*사건번호일련번호 */ FROM ACA710 A, ACA700 B, SAA000 C, SCA100 D /* 통합기관(C), 종사사(D) */ WHERE A.EMRG_CNTRMS_INCDNT_NO = B.EMRG_CNTRMS_INCDNT_NO AND A.INST_NO = C.INST_NO(+) AND A.PIC_NO = D.ENFSN_NO AND A.ACTN_RPT_YMD >= #{BGNG_YMD} AND A.ACTN_RPT_YMD <= #{END_YMD} AND B.INCDNT_TTL_NM LIKE '%'||#{INCDNT_TTL_NM}||'%'
AND C##RG.DEC_B64(D.FLNM_ENCPT) LIKE '%'||#{PIC_NM}||'%'
/* 상담복지센터는 모두 조회 */ /* 20230410_권한 쿼리_권한쿼리시작*/
/* 20230220_권한 쿼리_권한쿼리종료*/
ORDER BY A.ACTN_RPT_YMD DESC

mapper.delete:

 /* deleteData - Lee  MS */

DELETE FROM ACA710 /* 긴급대응조치 */
WHERE EMRG_CNTRMS_INCDNT_NO = #{EMRG_CNTRMS_INCDNT_NO}


 /* deleteDtlData - Lee  MS */

DELETE FROM ACA710 /* 긴급대응조치 */
WHERE EMRG_CNTRMS_INCDNT_NO = #{EMRG_CNTRMS_INCDNT_NO}
AND INCDNT_NO_SN = #{INCDNT_NO_SN}
